const item = $input.item.json;
const lead = item;
const u = item.usage || {};

let icp_score = 0;
let plg_score = 0;
let icp_signals = [];
let plg_signals = [];
let flags = [];

// ═══════════════════════════════════════════
// BLOCK A — ICP / FIRMOGRAPHIC SCORE (0–100)
// ═══════════════════════════════════════════

// A1. Industry fit (0–30)
const industryMap = {
  'dtc':30,'direct to consumer':30,'ecommerce':30,'e-commerce':30,
  'fashion':28,'apparel':28,'marketing agency':27,'creative agency':27,
  'agency':25,'media':24,'publishing':22,'saas':20,'software':18,
  'retail':18,'cpg':18,'food & beverage':16,
  'healthcare':6,'finance':4,'legal':3,'manufacturing':4
};
const ind = (lead.industry||'').toLowerCase();
let a1 = 0;
for (const [k,v] of Object.entries(industryMap)) {
  if (ind.includes(k)) { a1 = v; break; }
}
icp_score += a1;
if (a1 >= 25) icp_signals.push(`Strong industry: ${lead.industry}`);
else if (a1 >= 15) icp_signals.push(`Moderate industry: ${lead.industry}`);
else flags.push(`Weak industry fit: ${lead.industry}`);

// A2. Company size (0–25)
const emp = parseInt(lead.employees||0);
let a2 = 0;
if (emp>=50&&emp<=200)      { a2=25; icp_signals.push('Ideal size 50–200'); }
else if (emp<=500)           { a2=20; icp_signals.push('Good size 200–500'); }
else if (emp<=1000)          { a2=15; icp_signals.push('Acceptable size 500–1k'); }
else if (emp<=5000)          { a2=8;  flags.push('Large org — longer sales cycle'); }
else                         { a2=2;  flags.push('Enterprise — likely disqualify'); }
icp_score += a2;

// A3. Title / persona (0–25)
const title = (lead.title||'').toLowerCase();
const titleMap = [
  ['creative director',25],['head of creative',25],['vp creative',25],
  ['head of brand',23],['brand director',23],['content director',22],
  ['creative operations',25],['head of content',22],
  ['marketing director',20],['vp marketing',20],['cmo',20],
  ['creative manager',18],['brand manager',18],['content manager',18],
  ['social media manager',14],['marketing manager',14],['designer',10]
];
let a3 = 0;
for (const [k,v] of titleMap) { if (title.includes(k)) { a3=v; break; } }
icp_score += a3;
if (a3>=20) icp_signals.push(`Decision-maker: ${lead.title}`);
else if (a3>=12) icp_signals.push(`Relevant title: ${lead.title}`);
else flags.push(`Title not core ICP: ${lead.title}`);

// A4. Tech stack displacement signals (0–10)
const stack = (lead.tech_stack||'').toLowerCase();
const goodTools = ['dropbox','google drive','figma','adobe','frame.io','bynder','brandfolder'];
const alreadyAir = ['air.inc','airhq'];
let a4 = 0;
for (const t of goodTools) { if (stack.includes(t)) { a4 = Math.min(a4+3, 10); icp_signals.push(`Displacement: ${t}`); } }
for (const t of alreadyAir) { if (stack.includes(t)) { a4 = -99; flags.push('Already Air customer'); break; } }
icp_score += a4;

// A5. Geography (0–10)
const loc = (lead.location||'').toLowerCase();
let a5 = loc.includes('united states')||loc.includes('usa')||loc.includes(' us') ? 10
         : ['uk','canada','australia','united kingdom'].some(c=>loc.includes(c)) ? 7 : 3;
icp_score += a5;
if (a5===10) icp_signals.push('US market');

// Cap ICP
icp_score = Math.min(100, Math.max(0, icp_score));

// ═══════════════════════════════════════════
// BLOCK B — PLG / BEHAVIORAL SCORE (0–100)
// ═══════════════════════════════════════════

// B1. Storage pressure (0–25) — strongest PQL signal
const storageUsed = parseFloat(u.storage_used_gb||0);
const storageLimit = parseFloat(u.storage_limit_gb||5);
const storagePct = storageLimit > 0 ? storageUsed / storageLimit : 0;
const limitHits = parseInt(u.storage_limit_hit_count||0);
let b1 = 0;
if (limitHits >= 3)          { b1=25; plg_signals.push(`Hit storage limit ${limitHits}x — hot PQL`); }
else if (limitHits >= 1)     { b1=18; plg_signals.push(`Hit storage limit ${limitHits}x`); }
else if (storagePct >= 0.85) { b1=14; plg_signals.push(`${Math.round(storagePct*100)}% storage used`); }
else if (storagePct >= 0.6)  { b1=8;  plg_signals.push(`${Math.round(storagePct*100)}% storage used`); }
else if (u.plan === 'business') { b1=5; } // paid — no storage pressure but healthy
plg_score += b1;

// B2. Team expansion signals (0–20)
const invited = parseInt(u.team_members_invited||0);
const teamSize = parseInt(u.team_size||1);
let b2 = 0;
if (invited >= 4)            { b2=20; plg_signals.push(`Invited ${invited} teammates — viral expansion`); }
else if (invited >= 2)       { b2=14; plg_signals.push(`Invited ${invited} teammates`); }
else if (invited >= 1)       { b2=8;  plg_signals.push('Invited 1 teammate'); }
if (teamSize >= 5)           { b2 = Math.min(b2+5, 20); plg_signals.push(`Team of ${teamSize} active`); }
plg_score += b2;

// B3. Feature depth / power usage (0–20)
let b3 = 0;
if (u.ai_search_used==='true')            { b3+=6; plg_signals.push('Using AI search'); }
if (parseInt(u.approval_workflows_used||0)>=5) { b3+=6; plg_signals.push(`${u.approval_workflows_used} approval workflows`); }
else if (parseInt(u.approval_workflows_used||0)>=1) { b3+=3; plg_signals.push('Using approval workflows'); }
if (u.desktop_app_installed==='true')     { b3+=4; plg_signals.push('Desktop app installed'); }
if (u.canvas_used==='true')               { b3+=4; plg_signals.push('Using Canvas (AI feature)'); }
b3 = Math.min(b3, 20);
plg_score += b3;

// B4. Engagement frequency (0–20)
const daysActive = parseInt(u.days_active_30d||0);
const lastActive = parseInt(u.last_active_days_ago||99);
let b4 = 0;
if (daysActive >= 20)        { b4=15; plg_signals.push(`Active ${daysActive}/30 days`); }
else if (daysActive >= 12)   { b4=10; plg_signals.push(`Active ${daysActive}/30 days`); }
else if (daysActive >= 6)    { b4=5; }
else                         { flags.push(`Low engagement: only ${daysActive} active days`); }
if (lastActive <= 1)         { b4+=5; plg_signals.push('Active today or yesterday'); }
else if (lastActive > 10)    { flags.push(`Went dark ${lastActive} days ago`); }
b4 = Math.min(b4, 20);
plg_score += b4;

// B5. Sharing / collaboration breadth (0–15)
const shared = parseInt(u.assets_shared_externally||0);
let b5 = 0;
if (shared >= 30)            { b5=15; plg_signals.push(`${shared} assets shared externally`); }
else if (shared >= 10)       { b5=10; plg_signals.push(`${shared} assets shared externally`); }
else if (shared >= 3)        { b5=5; }
plg_score += b5;

// Cap PLG
plg_score = Math.min(100, Math.max(0, plg_score));

// ═══════════════════════════════════════════
// COMPOSITE SCORE + MOTION CLASSIFICATION
// ═══════════════════════════════════════════
// Weighted: 40% ICP fit, 60% PLG behavior
const composite = Math.round(icp_score * 0.40 + plg_score * 0.60);

// Motion classification
let motion, tier, needs_ai;
const plan = (u.plan||'free');

if (plan === 'business' && plg_score >= 50) {
  motion = 'Expansion';
} else if (plan === 'free' && composite >= 65) {
  motion = 'PQL';
} else if (composite >= 40) {
  motion = 'Churn';
} else if (flags.includes('Already Air customer')) {
  motion = 'Existing Customer';
} else {
  motion = 'Disqualify';
}

if (composite >= 70)      { tier = 'A'; needs_ai = false; }
else if (composite >= 50) { tier = 'B'; needs_ai = true; }
else if (composite >= 35) { tier = 'C'; needs_ai = true; }
else                      { tier = 'D'; needs_ai = false; }

return {
  ...lead,
  icp_score,
  plg_score,
  composite_score: composite,
  tier,
  motion,
  needs_ai,
  icp_signals,
  plg_signals,
  flags
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
// Separate leads from usage using a field only leads have
const leads = $input.all().filter(i => i.json.company);
const usageItems = $input.all().filter(i => !i.json.company);

// Build a lookup map from usage keyed by account_id
const usageMap = {};
usageItems.forEach(i => {
  usageMap[i.json.account_id] = i.json;
});

// Return one item per lead with usage nested inside
return leads.map(item => ({
  json: {
    ...item.json,
    usage: usageMap[item.json.account_id] || {}
  }
}));

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
return $input.all().map(item => ({
  json: {
    crm_contact_email: item.json.email,
    crm_lead_score: item.json.final_score,
    crm_motion: item.json.motion,
    crm_why_now: item.json.output?.why_now,
    crm_pain_hypothesis: item.json.output?.pain_hypothesis,
    crm_outreach_hook: item.json.output?.outreach_hook,
    crm_recommendation: item.json.recommendation,
    synced_at: new Date().toISOString()
  }
}));

