// Extract raw text from LLM response
const text = response.text 
  || response.message?.content 
  || response.content
  || response.output
  || JSON.stringify(response);

// Strip markdown if model wrapped it
const cleaned = text
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Parse JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  // Fallback — return what we have
  parsed = {
    account_id:         $('PLG + ICP Scoring').item.json.account_id || '',
    email:              $('PLG + ICP Scoring').item.json.email || '',
